import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { BulkScanJob } from "@/types";
import type { BulkScanJobRow } from "@/types/database";

// ── Query keys ───────────────────────────────────────────────────

export const bulkScanKeys = {
  all: ["bulk_scan_jobs"] as const,
  lists: () => [...bulkScanKeys.all, "list"] as const,
  list: (userId: string) => [...bulkScanKeys.lists(), userId] as const,
  detail: (id: string) => [...bulkScanKeys.all, "detail", id] as const,
};

// ── Row → App type mapper ────────────────────────────────────────

function rowToJob(row: BulkScanJobRow): BulkScanJob {
  return {
    id: row.id,
    user_id: row.user_id,
    team_id: row.team_id,
    status: row.status,
    urls: row.urls,
    page_type: row.page_type,
    total: row.total,
    completed: row.completed,
    failed: row.failed,
    created_at: row.created_at,
  };
}

// ── URL validation helpers ───────────────────────────────────────

/** Normalize a single URL string — prepend https:// if missing */
export function normalizeUrl(str: string): string {
  const trimmed = str.trim();
  if (!trimmed) return trimmed;
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  return `https://${trimmed}`;
}

/** Returns true if the normalized string is a valid http/https URL */
export function isValidUrl(str: string): boolean {
  try {
    const url = new URL(str);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

export interface ParsedUrlLine {
  lineNumber: number;
  raw: string;
  normalized: string;
  valid: boolean;
}

/** Parse a textarea value into per-line URL results */
export function parseUrlLines(raw: string): ParsedUrlLine[] {
  return raw
    .split("\n")
    .map((line, idx) => {
      const normalized = normalizeUrl(line);
      return {
        lineNumber: idx + 1,
        raw: line,
        normalized,
        valid: normalized.length > 0 && isValidUrl(normalized),
      };
    })
    .filter((l) => l.raw.trim().length > 0);
}

// ── useBulkScanJobs ──────────────────────────────────────────────

export function useBulkScanJobs() {
  const { user } = useAuth();

  return useQuery({
    queryKey: bulkScanKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<BulkScanJob[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as BulkScanJobRow[]).map(rowToJob);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30,
  });
}

// ── useBulkScanJob ───────────────────────────────────────────────

export function useBulkScanJob(jobId: string | undefined) {
  const { user } = useAuth();

  return useQuery({
    queryKey: bulkScanKeys.detail(jobId ?? ""),
    queryFn: async (): Promise<BulkScanJob | null> => {
      if (!jobId || !user?.id) return null;

      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .select("*")
        .eq("id", jobId)
        .eq("user_id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToJob(data as BulkScanJobRow);
    },
    enabled: !!jobId && !!user?.id,
    refetchInterval: (query) => {
      const job = query.state.data;
      if (!job) return false;
      return job.status === "pending" || job.status === "processing" ? 2000 : false;
    },
    staleTime: 0,
  });
}

// ── useCreateBulkScan ────────────────────────────────────────────

interface CreateBulkScanInput {
  urls: string[];
  page_type: string;
  team_id?: string | null;
}

export function useCreateBulkScan() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ urls, page_type, team_id }: CreateBulkScanInput): Promise<BulkScanJob> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Validate all URLs before inserting
      const invalid = urls.filter((u) => !isValidUrl(normalizeUrl(u)));
      if (invalid.length > 0) {
        throw new Error(`${invalid.length} invalid URL(s) detected. Please fix them before submitting.`);
      }

      const normalizedUrls = urls.map(normalizeUrl);

      // Insert the job row
      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .insert({
          user_id: user.id,
          team_id: team_id ?? null,
          status: "pending" as const,
          urls: normalizedUrls,
          page_type,
          total: normalizedUrls.length,
          completed: 0,
          failed: 0,
        })
        .select("*")
        .single();

      if (error) throw new Error(error.message);

      const job = rowToJob(data as BulkScanJobRow);

      // Fire the edge function — non-blocking
      supabase.functions
        .invoke("bulk-scan", {
          body: { job_id: job.id },
        })
        .catch((err: unknown) => {
          console.error("Bulk scan edge function invocation failed:", err);
          toast.error("Bulk scan engine failed to start. Please try again.", { duration: 6000 });
        });

      return job;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      // Prepend to list cache
      queryClient.setQueryData<BulkScanJob[]>(bulkScanKeys.list(user.id), (prev) =>
        prev ? [data, ...prev] : [data]
      );
      // Prime detail cache
      queryClient.setQueryData(bulkScanKeys.detail(data.id), data);
    },
  });
}

// ── useCancelBulkScan ────────────────────────────────────────────

export function useCancelBulkScan() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (jobId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("bulk_scan_jobs")
        .update({ status: "failed" })
        .eq("id", jobId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, jobId) => {
      if (!user?.id) return;
      // Update detail cache
      queryClient.setQueryData<BulkScanJob>(bulkScanKeys.detail(jobId), (prev) =>
        prev ? { ...prev, status: "failed" } : prev
      );
      // Update in list cache
      queryClient.setQueryData<BulkScanJob[]>(bulkScanKeys.list(user.id), (prev) =>
        prev ? prev.map((j) => (j.id === jobId ? { ...j, status: "failed" } : j)) : prev
      );
      toast.success("Bulk scan cancelled.");
    },
    onError: (err: unknown) => {
      const message = err instanceof Error ? err.message : "Failed to cancel job";
      toast.error(message);
    },
  });
}

/**
 * bulk-scan — Edge Function
 *
 * Processes a bulk scan job by iterating over each URL and invoking
 * the analyze-url function for each one. Individual URL failures are
 * non-fatal — they increment the failed counter and allow the batch
 * to continue.
 *
 * Required env vars:
 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function corsResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Delay helper ──────────────────────────────────────────────

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// ── Bulk scan job shape (minimal — only what we need) ─────────

interface BulkScanJobRow {
  id: string;
  user_id: string;
  team_id: string | null;
  status: string;
  urls: string[];
  page_type: string;
  total: number;
  completed: number;
  failed: number;
}

// ── Main handler ──────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  // ── Auth ──────────────────────────────────────────────────

  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return corsResponse({ error: "Missing authorization header" }, 401);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!supabaseUrl || !serviceRoleKey) {
    return corsResponse({ error: "Server configuration error" }, 500);
  }

  // User client — to validate ownership
  const userClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY") ?? "", {
    global: { headers: { Authorization: authHeader } },
  });

  const {
    data: { user },
    error: userError,
  } = await userClient.auth.getUser();

  if (userError || !user) {
    return corsResponse({ error: "Unauthorized" }, 401);
  }

  // Service-role client — to update job rows without RLS restrictions
  const adminClient = createClient(supabaseUrl, serviceRoleKey);

  // ── Parse body ────────────────────────────────────────────

  let jobId: string;
  try {
    const body = await req.json() as { job_id?: string };
    if (!body.job_id) throw new Error("Missing job_id");
    jobId = body.job_id;
  } catch {
    return corsResponse({ error: "Invalid request body — expected { job_id }" }, 400);
  }

  // ── Fetch & validate job ──────────────────────────────────

  const { data: jobData, error: fetchError } = await adminClient
    .from("bulk_scan_jobs")
    .select("*")
    .eq("id", jobId)
    .single();

  if (fetchError || !jobData) {
    return corsResponse({ error: "Job not found" }, 404);
  }

  const job = jobData as BulkScanJobRow;

  if (job.user_id !== user.id) {
    return corsResponse({ error: "Forbidden" }, 403);
  }

  if (job.status !== "pending") {
    return corsResponse({ error: "Job is not in pending state", status: job.status }, 409);
  }

  // ── Mark as processing ────────────────────────────────────

  await adminClient
    .from("bulk_scan_jobs")
    .update({ status: "processing" })
    .eq("id", jobId);

  // ── Process each URL (non-blocking response) ──────────────
  // We return immediately and process in the background. Deno edge
  // functions support this via EdgeRuntime.waitUntil when available,
  // but we can also return early and let the function keep running.

  const functionsUrl = `${supabaseUrl}/functions/v1`;

  async function processAllUrls() {
    let completedCount = 0;
    let failedCount = 0;

    for (const url of job.urls) {
      try {
        // Insert a scan row for this URL
        const { data: scanData, error: scanInsertError } = await adminClient
          .from("scans")
          .insert({
            user_id: job.user_id,
            url,
            page_type: job.page_type,
            status: "pending",
            ...(job.team_id ? { team_id: job.team_id } : {}),
          })
          .select("id")
          .single();

        if (scanInsertError || !scanData) {
          throw new Error(scanInsertError?.message ?? "Failed to insert scan row");
        }

        const scanId = (scanData as { id: string }).id;

        // Invoke analyze-url for this scan
        const analyzeResponse = await fetch(`${functionsUrl}/analyze-url`, {
          method: "POST",
          headers: {
            Authorization: authHeader,
            "Content-Type": "application/json",
            apikey: Deno.env.get("SUPABASE_ANON_KEY") ?? "",
          },
          body: JSON.stringify({ scan_id: scanId, url, page_type: job.page_type }),
        });

        if (!analyzeResponse.ok) {
          const errText = await analyzeResponse.text().catch(() => "unknown error");
          throw new Error(`analyze-url returned ${analyzeResponse.status}: ${errText}`);
        }

        completedCount++;
      } catch (err) {
        console.error(`bulk-scan: failed to process URL ${url}:`, err);
        failedCount++;
      }

      // Update progress counters after each URL
      await adminClient
        .from("bulk_scan_jobs")
        .update({ completed: completedCount, failed: failedCount })
        .eq("id", jobId);

      // Rate-limit guard between URLs
      await delay(500);
    }

    // Final status update
    const finalStatus = completedCount === 0 && failedCount > 0 ? "failed" : "completed";
    await adminClient
      .from("bulk_scan_jobs")
      .update({ status: finalStatus, completed: completedCount, failed: failedCount })
      .eq("id", jobId);
  }

  // Fire and forget — return immediately so the client isn't blocked
  processAllUrls().catch((err: unknown) => {
    console.error("bulk-scan: processAllUrls threw unexpectedly:", err);
    adminClient
      .from("bulk_scan_jobs")
      .update({ status: "failed" })
      .eq("id", jobId)
      .then(() => {})
      .catch(() => {});
  });

  return corsResponse({ job_id: jobId, status: "processing" });
});

import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { AlertCircle, CheckCircle2, Layers } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PAGE_TYPES } from "@/lib/constants";
import { useAuth } from "@/contexts/AuthContext";
import { useCreateBulkScan, parseUrlLines } from "@/hooks/use-bulk-scan";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

interface BulkScanDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function BulkScanDialog({ open, onOpenChange }: BulkScanDialogProps) {
  const navigate = useNavigate();
  const { profile } = useAuth();
  const createBulkScan = useCreateBulkScan();

  const [rawText, setRawText] = useState("");
  const [pageType, setPageType] = useState<string>("landing");

  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 0;
  const scansRemaining = Math.max(0, scanLimit - scansUsed);

  const parsedLines = useMemo(() => parseUrlLines(rawText), [rawText]);
  const validLines = parsedLines.filter((l) => l.valid);
  const invalidLines = parsedLines.filter((l) => !l.valid);

  const urlCount = validLines.length;
  const overLimit = urlCount > scansRemaining;
  const canSubmit = urlCount > 0 && invalidLines.length === 0 && !overLimit;

  function handleSubmit() {
    if (!canSubmit) return;

    const urls = validLines.map((l) => l.normalized);

    createBulkScan.mutate(
      { urls, page_type: pageType },
      {
        onSuccess: (job) => {
          toast.success(`Batch scan started for ${job.total} URLs.`, {
            description: "Track progress in Reports.",
            action: {
              label: "View Reports",
              onClick: () => navigate("/reports"),
            },
            duration: 8000,
          });
          setRawText("");
          onOpenChange(false);
        },
        onError: (err: unknown) => {
          const message = err instanceof Error ? err.message : "Failed to start batch scan";
          toast.error(message);
        },
      }
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Layers className="h-4.5 w-4.5 text-primary" />
            Bulk URL Scan
          </DialogTitle>
          <DialogDescription>
            Paste URLs below — one per line. We'll run a full CRO audit on each.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* URL textarea */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <label className="text-sm font-medium text-foreground">URLs</label>
              {urlCount > 0 && (
                <span
                  className={cn(
                    "text-xs font-medium tabular-nums",
                    overLimit ? "text-red-600" : "text-emerald-600"
                  )}
                >
                  {urlCount} URL{urlCount !== 1 ? "s" : ""} detected
                </span>
              )}
            </div>
            <Textarea
              rows={8}
              placeholder={
                "https://example.com/landing\nhttps://mystore.com/product/shoes\nhttps://saas.io/pricing"
              }
              value={rawText}
              onChange={(e) => setRawText(e.target.value)}
              className={cn(
                "resize-none font-mono text-sm",
                invalidLines.length > 0 && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
              )}
            />

            {/* Invalid URL errors */}
            {invalidLines.length > 0 && (
              <ul className="mt-1 space-y-0.5">
                {invalidLines.map((l) => (
                  <li key={l.lineNumber} className="flex items-start gap-1 text-xs text-red-600">
                    <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                    <span>
                      Line {l.lineNumber}: <span className="font-mono">{l.raw.trim() || "(empty)"}</span> — invalid URL
                    </span>
                  </li>
                ))}
              </ul>
            )}

            {/* Over limit warning */}
            {overLimit && invalidLines.length === 0 && (
              <p className="flex items-center gap-1 text-xs text-red-600">
                <AlertCircle className="h-3.5 w-3.5 shrink-0" />
                {urlCount} URLs exceeds your remaining quota ({scansRemaining} left this month).
              </p>
            )}
          </div>

          {/* Page type selector */}
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-foreground">Page type</label>
            <Select value={pageType} onValueChange={setPageType}>
              <SelectTrigger>
                <SelectValue placeholder="Select page type" />
              </SelectTrigger>
              <SelectContent>
                {PAGE_TYPES.map((type) => (
                  <SelectItem key={type.value} value={type.value}>
                    {type.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              Applied to all URLs in this batch.
            </p>
          </div>

          {/* Quota summary */}
          <div className="flex items-center gap-2 rounded-lg border border-border/40 bg-muted/30 px-3 py-2">
            <CheckCircle2 className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            <span className="text-xs text-muted-foreground">
              {scansRemaining} scan{scansRemaining !== 1 ? "s" : ""} remaining this month
            </span>
            <Badge variant="secondary" className="ml-auto text-2xs font-medium">
              {profile?.plan ?? "free"}
            </Badge>
          </div>
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={createBulkScan.isPending}
          >
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={!canSubmit || createBulkScan.isPending}
          >
            {createBulkScan.isPending ? (
              <>
                <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
                Starting...
              </>
            ) : (
              <>
                <Layers className="mr-2 h-4 w-4" />
                Start Batch Scan{urlCount > 0 ? ` (${urlCount})` : ""}
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { CheckCircle2, XCircle, Loader2, Clock, ChevronDown, ChevronUp, X } from "lucide-react";
import { useState } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import type { BulkScanJob, BulkScanJobStatus } from "@/types";
import { useBulkScanJob, useCancelBulkScan } from "@/hooks/use-bulk-scan";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";

// ── Status display helpers ────────────────────────────────────────

const STATUS_CONFIG: Record<
  BulkScanJobStatus,
  { label: string; variant: "default" | "secondary" | "destructive" | "outline"; className: string }
> = {
  pending: {
    label: "Pending",
    variant: "secondary",
    className: "bg-amber-50 text-amber-700 border-amber-200",
  },
  processing: {
    label: "Processing",
    variant: "default",
    className: "bg-blue-50 text-blue-700 border-blue-200",
  },
  completed: {
    label: "Completed",
    variant: "default",
    className: "bg-emerald-50 text-emerald-700 border-emerald-200",
  },
  failed: {
    label: "Failed",
    variant: "destructive",
    className: "bg-red-50 text-red-700 border-red-200",
  },
};

// ── Per-URL status icon ───────────────────────────────────────────

function UrlStatusIcon({
  index,
  completed,
  failed,
  total,
  isActive,
}: {
  index: number;
  completed: number;
  failed: number;
  total: number;
  isActive: boolean;
}) {
  const processedCount = completed + failed;

  if (index < completed) {
    // This slot completed successfully
    return <CheckCircle2 className="h-3.5 w-3.5 shrink-0 text-emerald-500" />;
  }
  if (index >= completed && index < completed + failed) {
    // This slot failed
    return <XCircle className="h-3.5 w-3.5 shrink-0 text-red-500" />;
  }
  if (isActive && index === processedCount && index < total) {
    // This slot is currently being processed
    return <Loader2 className="h-3.5 w-3.5 shrink-0 animate-spin text-blue-500" />;
  }
  // Queued
  return <Clock className="h-3.5 w-3.5 shrink-0 text-muted-foreground/50" />;
}

// ── Inner card that polls when given a jobId ──────────────────────

function PollingBulkScanCard({ jobId }: { jobId: string }) {
  const { data: job } = useBulkScanJob(jobId);
  if (!job) return null;
  return <BulkScanProgressCard job={job} />;
}

// ── Main card component ───────────────────────────────────────────

interface BulkScanProgressCardProps {
  job: BulkScanJob;
}

function BulkScanProgressCard({ job }: BulkScanProgressCardProps) {
  const [urlsExpanded, setUrlsExpanded] = useState(false);
  const cancelJob = useCancelBulkScan();

  const statusConfig = STATUS_CONFIG[job.status];
  const processedCount = job.completed + job.failed;
  const remaining = job.total - processedCount;
  const progressPercent = job.total > 0 ? Math.round((processedCount / job.total) * 100) : 0;
  const isActive = job.status === "pending" || job.status === "processing";

  const visibleUrls = urlsExpanded ? job.urls : job.urls.slice(0, 5);

  function handleCancel() {
    cancelJob.mutate(job.id);
  }

  return (
    <Card className="border-border/40 shadow-soft overflow-hidden">
      <CardHeader className="flex flex-row items-start justify-between gap-3 pb-3 pt-4 px-4">
        <div className="flex min-w-0 flex-col gap-1">
          <div className="flex items-center gap-2 flex-wrap">
            <Badge
              variant="outline"
              className={cn("text-xs font-medium", statusConfig.className)}
            >
              {isActive && <Loader2 className="mr-1 h-3 w-3 animate-spin" />}
              {statusConfig.label}
            </Badge>
            <span className="text-xs text-muted-foreground tabular-nums">
              {job.total} URL{job.total !== 1 ? "s" : ""}
            </span>
          </div>
          <span className="text-xs text-muted-foreground">
            Started {formatDistanceToNow(new Date(job.created_at), { addSuffix: true })}
          </span>
        </div>

        {isActive && (
          <Button
            variant="ghost"
            size="sm"
            className="h-7 w-7 p-0 shrink-0 text-muted-foreground hover:text-destructive"
            onClick={handleCancel}
            disabled={cancelJob.isPending}
            title="Cancel batch"
          >
            <X className="h-4 w-4" />
          </Button>
        )}
      </CardHeader>

      <CardContent className="space-y-3 px-4 pb-4">
        {/* Progress bar */}
        <div className="space-y-1.5">
          <div className="flex justify-between text-xs text-muted-foreground">
            <span>{processedCount} of {job.total} processed</span>
            <span className="tabular-nums font-medium text-foreground">{progressPercent}%</span>
          </div>
          <Progress
            value={progressPercent}
            className={cn(
              "h-2",
              job.status === "failed" && "**:[&>*]:bg-red-500",
              job.status === "completed" && "**:[&>*]:bg-emerald-500"
            )}
          />
        </div>

        {/* Stats row */}
        <div className="flex items-center gap-4 text-xs">
          <span className="flex items-center gap-1.5 text-emerald-600">
            <CheckCircle2 className="h-3.5 w-3.5" />
            {job.completed} completed
          </span>
          {job.failed > 0 && (
            <span className="flex items-center gap-1.5 text-red-600">
              <XCircle className="h-3.5 w-3.5" />
              {job.failed} failed
            </span>
          )}
          {remaining > 0 && (
            <span className="flex items-center gap-1.5 text-muted-foreground">
              <Clock className="h-3.5 w-3.5" />
              {remaining} remaining
            </span>
          )}
        </div>

        {/* URL list */}
        <div className="rounded-lg border border-border/40 bg-muted/20">
          <ul className="divide-y divide-border/30">
            {visibleUrls.map((url, i) => (
              <li key={url} className="flex items-center gap-2 px-3 py-2">
                <UrlStatusIcon
                  index={i}
                  completed={job.completed}
                  failed={job.failed}
                  total={job.total}
                  isActive={isActive}
                />
                <span className="min-w-0 truncate font-mono text-xs text-muted-foreground" title={url}>
                  {url}
                </span>
              </li>
            ))}
          </ul>
          {job.urls.length > 5 && (
            <button
              type="button"
              onClick={() => setUrlsExpanded((prev) => !prev)}
              className="flex w-full items-center justify-center gap-1 border-t border-border/30 py-2 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              {urlsExpanded ? (
                <>
                  <ChevronUp className="h-3.5 w-3.5" />
                  Show less
                </>
              ) : (
                <>
                  <ChevronDown className="h-3.5 w-3.5" />
                  {job.urls.length - 5} more URL{job.urls.length - 5 !== 1 ? "s" : ""}
                </>
              )}
            </button>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

// ── Exports ───────────────────────────────────────────────────────

/**
 * Pass either a full `job` object (for the list view that already has data)
 * or a `jobId` string (for isolated polling of a single job).
 */
export function BulkScanProgress({ job, jobId }: { job?: BulkScanJob; jobId?: string }) {
  if (job) return <BulkScanProgressCard job={job} />;
  if (jobId) return <PollingBulkScanCard jobId={jobId} />;
  return null;
}

