124	// ── Component ───────────────────────────────────────────────────
125	
126	const Reports = () => {
127	  const navigate = useNavigate();
128	  const [search, setSearch] = useState("");
129	  const [statusFilter, setStatusFilter] = useState("all");
130	  const [scoreFilter, setScoreFilter] = useState("all");
131	  const [sortBy, setSortBy] = useState("newest");
132	
133	  const { data: scans = [], isLoading, isError, refetch } = useScans();
134	  const deleteScan = useDeleteScan();
135	  const { profile } = useAuth();
136	  const { isMonitored, toggleMonitoring } = useMonitoring();
137	  const canMonitor = profile?.plan === "pro" || profile?.plan === "agency";
138	
139	  const hasActiveFilters = search || statusFilter !== "all" || scoreFilter !== "all";
140	
141	  const clearFilters = () => {
142	    setSearch("");
143	    setStatusFilter("all");
144	    setScoreFilter("all");
145	    setSortBy("newest");
146	  };
147	
148	  const filtered = useMemo(() => {
149	    let list = [...scans];
150	
151	    if (search) {
152	      const q = search.toLowerCase();
153	      list = list.filter(
154	        (s) =>
155	          s.url.toLowerCase().includes(q) ||
156	          (s.page_title?.toLowerCase().includes(q) ?? false)
157	      );
158	    }
159	
160	    if (statusFilter !== "all") {
161	      list = list.filter((s) => s.status === statusFilter);
162	    }
163	
164	    if (scoreFilter !== "all") {
165	      list = list.filter((s) => {
166	        if (s.overall_score === null) return false;
167	        if (scoreFilter === "poor") return s.overall_score < 40;
168	        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
169	        if (scoreFilter === "good") return s.overall_score >= 70;
170	        return true;
171	      });
172	    }
173	
174	    list.sort((a, b) => {
175	      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
176	      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
177	      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
178	      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
179	      return 0;
180	    });
181	
182	    return list;
183	  }, [scans, search, statusFilter, scoreFilter, sortBy]);
184	
185	  const handleDelete = (scanId: string, hostname: string) => {
186	    deleteScan.mutate(scanId, {
187	      onSuccess: () => toast.success(`Scan for ${hostname} deleted`),
188	      onError: () => toast.error("Failed to delete scan"),
189	    });
190	  };
191	
192	  return (
193	    <PageTransition>
194	      <div className="space-y-6">
195	        <PageHeader title="My Reports" description="View and manage your CRO audit reports">
196	          <Button asChild>
197	            <Link to="/scan">
198	              <ScanLine className="mr-2 h-4 w-4" />
199	              New Scan
200	            </Link>
201	          </Button>
202	        </PageHeader>
203	
204	        {/* Filter Bar */}
205	        <Card className="border-border/40 shadow-soft">
206	          <CardContent className="p-4">
207	            <div className="flex flex-wrap items-center gap-3">
208	              <div className="relative flex-1 min-w-[200px]">
209	                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
210	                <Input
211	                  placeholder="Search by URL or page title..."
212	                  value={search}
213	                  onChange={(e) => setSearch(e.target.value)}
214	                  className="pl-9"
215	                />
216	              </div>
217	              <Select value={statusFilter} onValueChange={setStatusFilter}>
218	                <SelectTrigger className="w-36">
219	                  <SelectValue placeholder="Status" />
220	                </SelectTrigger>
221	                <SelectContent>
222	                  <SelectItem value="all">All Status</SelectItem>
223	                  <SelectItem value="completed">Completed</SelectItem>
224	                  <SelectItem value="analyzing">Analyzing</SelectItem>
225	                  <SelectItem value="failed">Failed</SelectItem>
226	                </SelectContent>
227	              </Select>
228	              <Select value={scoreFilter} onValueChange={setScoreFilter}>
229	                <SelectTrigger className="w-36">
230	                  <SelectValue placeholder="Score" />
231	                </SelectTrigger>
232	                <SelectContent>
233	                  <SelectItem value="all">All Scores</SelectItem>
234	                  <SelectItem value="poor">Poor (0-40)</SelectItem>
235	                  <SelectItem value="average">Average (40-70)</SelectItem>
236	                  <SelectItem value="good">Good (70+)</SelectItem>
237	                </SelectContent>
238	              </Select>
239	              <Select value={sortBy} onValueChange={setSortBy}>
240	                <SelectTrigger className="w-36">
241	                  <SelectValue placeholder="Sort" />
242	                </SelectTrigger>
243	                <SelectContent>
244	                  <SelectItem value="newest">Newest First</SelectItem>
245	                  <SelectItem value="oldest">Oldest First</SelectItem>
246	                  <SelectItem value="score-high">Score: High-Low</SelectItem>
247	                  <SelectItem value="score-low">Score: Low-High</SelectItem>
248	                </SelectContent>
249	              </Select>
250	              {hasActiveFilters && (
251	                <Button variant="ghost" size="sm" onClick={clearFilters} className="text-muted-foreground hover:text-foreground h-9">
252	                  <X className="mr-1.5 h-3.5 w-3.5" />
253	                  Clear Filters
254	                </Button>
255	              )}
256	            </div>
257	          </CardContent>
258	        </Card>
259	
260	        {/* Data Table */}
261	        {isLoading ? (
262	          <ReportTableSkeleton />
263	        ) : isError ? (
264	          <ErrorState
265	            title="Failed to load reports"
266	            description="There was a problem fetching your scan reports. Check your connection and try again."
267	            onRetry={() => void refetch()}
268	          />
269	        ) : filtered.length > 0 ? (
270	          <Card className="border-border/40 shadow-soft overflow-hidden">
271	            <div className="overflow-x-auto scrollbar-thin">
272	              <Table>
273	                <TableHeader>
274	                  <TableRow className="hover:bg-transparent bg-muted/20">
275	                    <TableHead className="pl-5 min-w-[240px]">Website</TableHead>
276	                    <TableHead className="w-[100px]">Score</TableHead>
277	                    <TableHead className="w-[90px]">Issues</TableHead>
278	                    <TableHead className="w-[90px]">Type</TableHead>
279	                    <TableHead className="w-[100px]">Status</TableHead>
280	                    <TableHead className="w-[100px]">Date</TableHead>
281	                    <TableHead className="w-[50px] pr-5" />
282	                  </TableRow>
283	                </TableHeader>
284	                <TableBody>
285	                  {filtered.map((scan) => {
286	                    let hostname = scan.url;
287	                    try { hostname = new URL(scan.url).hostname; } catch { /* keep raw */ }
288	                    const displayHostname = hostname.replace("www.", "");
289	                    const faviconUrl = `https://www.google.com/s2/favicons?domain=${hostname}&sz=32`;
290	
291	                    return (
292	                      <TableRow
293	                        key={scan.id}
294	                        className="group cursor-pointer"
295	                        onClick={() => navigate(`/reports/${scan.id}`)}
296	                      >
297	                        {/* Website */}
298	                        <TableCell className="pl-5">
299	                          <div className="flex items-center gap-3">
300	                            <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-muted/40 overflow-hidden">
301	                              <img
302	                                src={faviconUrl}
303	                                alt=""
304	                                className="h-4 w-4"
305	                                onError={(e) => {
306	                                  e.currentTarget.style.display = "none";
307	                                  const parent = e.currentTarget.parentElement;
308	                                  if (parent && !parent.querySelector("svg")) {
309	                                    const fallback = document.createElement("span");
310	                                    fallback.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-muted-foreground"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>`;
311	                                    parent.appendChild(fallback);
312	                                  }
313	                                }}
314	                              />
315	                            </div>
316	                            <div className="min-w-0">
317	                              <p className="truncate text-sm font-medium text-foreground max-w-[200px]">
318	                                {scan.page_title ?? displayHostname}
319	                              </p>
320	                              <p className="truncate text-xs text-muted-foreground max-w-[200px]">
321	                                {displayHostname}
322	                              </p>
323	                            </div>
324	                          </div>
325	                        </TableCell>
326	
327	                        {/* Score */}
328	                        <TableCell>
329	                          {scan.overall_score !== null ? (
330	                            <div className="flex items-center gap-2">
331	                              <ScoreRing score={scan.overall_score} size={28} strokeWidth={3} showLabel={false} />
332	                              <span className={cn("text-sm font-semibold tabular-nums", getScoreColor(scan.overall_score))}>
333	                                {scan.overall_score}
334	                              </span>
335	                            </div>
336	                          ) : (
337	                            <span className="text-xs text-muted-foreground">--</span>
338	                          )}
339	                        </TableCell>
340	
341	                        {/* Issues */}
342	                        <TableCell>
343	                          <span className="text-sm text-muted-foreground tabular-nums">
344	                            {scan.issues_found}
345	                            {scan.critical_issues > 0 && (
346	                              <span className="ml-1 text-red-500 font-medium">
347	                                ({scan.critical_issues})
348	                              </span>
349	                            )}
350	                          </span>
351	                        </TableCell>
352	
353	                        {/* Type */}
354	                        <TableCell>
355	                          <Badge variant="outline" className="text-xs capitalize">
356	                            {scan.page_type}
357	                          </Badge>
358	                        </TableCell>
359	
360	                        {/* Status */}
361	                        <TableCell>
362	                          <div className="flex items-center gap-1.5">
363	                            {getStatusBadge(scan.status)}
364	                            {canMonitor && isMonitored(scan.url) && (
365	                              <Bell className="h-3 w-3 text-primary" />
366	                            )}
367	                          </div>
368	                        </TableCell>
369	
370	                        {/* Date */}
371	                        <TableCell className="text-sm text-muted-foreground">
372	                          {formatDate(scan.created_at)}
373	                        </TableCell>
374	
375	                        {/* Actions */}
376	                        <TableCell className="pr-5">
377	                          <DropdownMenu>
378	                            <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
379	                              <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
380	                                <MoreVertical className="h-4 w-4 text-muted-foreground" />
381	                              </Button>
382	                            </DropdownMenuTrigger>
383	                            <DropdownMenuContent align="end">
384	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); navigate(`/reports/${scan.id}`); }}>
385	                                <Eye className="mr-2 h-3.5 w-3.5" /> View Report
386	                              </DropdownMenuItem>
387	                              <DropdownMenuItem onClick={(e) => { e.stopPropagation(); navigate(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`); }}>
388	                                <RefreshCw className="mr-2 h-3.5 w-3.5" /> Re-scan
389	                              </DropdownMenuItem>
390	                              <DropdownMenuSeparator />
391	                              {canMonitor ? (
392	                                <DropdownMenuItem
393	                                  onClick={(e) => {
394	                                    e.stopPropagation();
395	                                    const wasMonitored = isMonitored(scan.url);
396	                                    toggleMonitoring(scan.url);
397	                                    toast.success(
398	                                      wasMonitored
399	                                        ? "Monitoring disabled for this URL"
400	                                        : "Monthly monitoring enabled — you'll get alerts when the score drops"
401	                                    );
402	                                  }}
403	                                >
404	                                  {isMonitored(scan.url) ? (
405	                                    <><BellOff className="mr-2 h-3.5 w-3.5 text-muted-foreground" />Stop Monitoring</>
406	                                  ) : (
407	                                    <><Bell className="mr-2 h-3.5 w-3.5" />Monitor Monthly</>
408	                                  )}
409	                                </DropdownMenuItem>
410	                              ) : (
411	                                <DropdownMenuItem disabled className="opacity-50">
412	                                  <Bell className="mr-2 h-3.5 w-3.5" />
413	                                  Monitor Monthly
414	                                  <Badge variant="outline" className="ml-auto text-2xs border-amber-200 bg-amber-50 text-amber-700">Pro</Badge>
415	                                </DropdownMenuItem>
416	                              )}
417	                              <DropdownMenuSeparator />
418	                              <DropdownMenuItem
419	                                className="text-red-600"
420	                                onClick={(e) => {
421	                                  e.stopPropagation();
422	                                  handleDelete(scan.id, displayHostname);
423	                                }}
424	                              >
425	                                <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete
426	                              </DropdownMenuItem>
427	                            </DropdownMenuContent>
428	                          </DropdownMenu>
429	                        </TableCell>
430	                      </TableRow>
431	                    );
432	                  })}
433	                </TableBody>
434	              </Table>
435	            </div>
436	
437	            {/* Results count */}
438	            <div className="border-t border-border/30 bg-muted/10 px-5 py-3">
439	              <p className="text-xs text-muted-foreground">
440	                Showing {filtered.length} of {scans.length} report{scans.length !== 1 ? "s" : ""}
441	              </p>
442	            </div>
443	          </Card>
444	        ) : (
445	          <EmptyState
446	            icon={ScanLine}
447	            title="No reports found"
448	            description={
449	              hasActiveFilters
450	                ? "Try adjusting your filters to find what you're looking for."
451	                : "Run your first CRO audit to see results here."
452	            }
453	            actionLabel="Start New Scan"
454	            actionHref="/scan"
455	          />
456	        )}
457	      </div>
458	    </PageTransition>
459	  );
460	};
461	
462	export default Reports;
